import AppKit
import CryptoKit

/// Polls the general pasteboard every 0.5 s and stores text, URLs and images as clipboard items.
/// Items marked concealed/transient (password managers) are never read or stored.
final class ClipboardWatcher {
    static let skippedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
    ]
    static let maxTextLength = 200_000

    private let pasteboard = NSPasteboard.general
    private var lastChangeCount: Int
    private var timer: Timer?
    private let queue = DispatchQueue(label: "recall.clipboard", qos: .utility)
    var onStored: (() -> Void)?

    init() { lastChangeCount = NSPasteboard.general.changeCount }

    var isRunning: Bool { timer != nil }

    func start() {
        guard timer == nil else { return }
        lastChangeCount = pasteboard.changeCount // don't import whatever was copied before
        let t = Timer(timeInterval: 0.5, repeats: true) { [weak self] _ in self?.poll() }
        t.tolerance = 0.2
        RunLoop.main.add(t, forMode: .common)
        timer = t
    }

    func stop() {
        timer?.invalidate()
        timer = nil
    }

    private func poll() {
        let count = pasteboard.changeCount
        guard count != lastChangeCount else { return }
        lastChangeCount = count
        guard let captured = capture() else { return }
        queue.async { [weak self] in
            if ClipboardStore.store(captured) { DispatchQueue.main.async { self?.onStored?() } }
        }
    }

    /// Reads the pasteboard on the main thread (cheap); heavy work happens later on a background queue.
    private func capture() -> ClipboardStore.Captured? {
        guard let item = pasteboard.pasteboardItems?.first else { return nil }
        let types = Set(item.types.map(\.rawValue))
        if !types.isDisjoint(with: Self.skippedTypes) { return nil }
        if types.contains(ClipboardStore.ownMarker) { return nil } // re-copied by Recall itself

        // Copied files are already covered by file indexing.
        if types.contains(NSPasteboard.PasteboardType.fileURL.rawValue) { return nil }

        if let s = item.string(forType: .URL) ?? item.string(forType: NSPasteboard.PasteboardType("public.url")),
           let url = URL(string: s), url.scheme != nil {
            return .url(url.absoluteString)
        }
        if let s = item.string(forType: .string) {
            let trimmed = s.trimmingCharacters(in: .whitespacesAndNewlines)
            guard !trimmed.isEmpty else { return nil }
            if !trimmed.contains(where: \.isWhitespace), let url = URL(string: trimmed),
               let scheme = url.scheme?.lowercased(), ["http", "https"].contains(scheme) {
                return .url(trimmed)
            }
            return .text(String(s.prefix(Self.maxTextLength)))
        }
        if let data = item.data(forType: .png) ?? item.data(forType: .tiff) {
            return .image(data)
        }
        return nil
    }
}

/// Writes clipboard captures to the database and handles retention.
enum ClipboardStore {
    static let ownMarker = "dev.recall.own-copy"

    enum Captured {
        case text(String)
        case url(String)
        case image(Data)
    }

    static var clipsDirectory: URL {
        let dir = AppDatabase.supportDirectory.appendingPathComponent("clips", isDirectory: true)
        try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        return dir
    }

    /// Stores a capture. A repeat of an existing clip just moves it to the top. Returns true if stored.
    @discardableResult
    static func store(_ c: Captured, at date: Date = Date()) -> Bool {
        let db = AppDatabase.shared
        let hash: String
        switch c {
        case .text(let s): hash = sha256(Data(("text:" + s).utf8))
        case .url(let s): hash = sha256(Data(("url:" + s).utf8))
        case .image(let d): hash = sha256(d)
        }
        if (try? db.bumpClipboardItem(hash: hash, to: date)) == true { return true }

        var fields = AppDatabase.ItemFields(
            source: .clipboard, path: nil, title: "", kind: "text", createdAt: date, modifiedAt: date,
            size: 0, contentHash: hash, thumbnailPath: nil, metadataJSON: nil)
        var text = ""
        switch c {
        case .text(let s):
            text = s
            fields.title = title(for: s)
            fields.size = Int64(s.utf8.count)
            fields.metadataJSON = json(["text": s])
        case .url(let s):
            text = s
            fields.kind = "url"
            fields.title = s
            fields.size = Int64(s.utf8.count)
            fields.metadataJSON = json(["url": s])
        case .image(let data):
            guard let rep = NSBitmapImageRep(data: data), let png = rep.representation(using: .png, properties: [:]),
                  let cg = rep.cgImage else { return false }
            let file = clipsDirectory.appendingPathComponent(hash.prefix(24) + ".png")
            do { try png.write(to: file) } catch { return false }
            text = ImageExtractor.recognizeText(in: cg)
            fields.kind = "image"
            fields.title = text.isEmpty ? "Copied image" : "Image: " + title(for: text)
            fields.size = Int64(png.count)
            fields.metadataJSON = json(["image": file.path])
            if let src = CGImageSourceCreateWithData(png as CFData, nil) {
                fields.thumbnailPath = ImageExtractor.writeThumbnail(src, key: file.path)
            }
        }
        do {
            try db.upsert(fields, chunks: Chunker.chunks(text))
            return true
        } catch {
            NSLog("Recall: failed to store clipboard item: \(error)")
            return false
        }
    }

    /// Deletes clipboard items older than the retention period, plus their saved images.
    static func applyRetention(days: Int) {
        let cutoff = Date().addingTimeInterval(-Double(days) * 86_400)
        let removed = (try? AppDatabase.shared.deleteClipboardItems(before: cutoff)) ?? []
        removeFiles(removed)
    }

    static func deleteAll() {
        let removed = (try? AppDatabase.shared.deleteClipboardItems(before: .distantFuture)) ?? []
        removeFiles(removed)
    }

    private static func removeFiles(_ metadata: [AppDatabase.ClipboardFiles]) {
        for m in metadata {
            for path in [m.imagePath, m.thumbnailPath].compactMap({ $0 }) {
                try? FileManager.default.removeItem(atPath: path)
            }
        }
    }

    /// Puts a clipboard item back on the pasteboard.
    static func copyToPasteboard(itemId: Int64) -> Bool {
        guard let meta = AppDatabase.shared.metadata(itemId: itemId) else { return false }
        let pb = NSPasteboard.general
        pb.clearContents()
        let item = NSPasteboardItem()
        item.setString("1", forType: NSPasteboard.PasteboardType(ownMarker))
        if let text = meta["text"] as? String {
            item.setString(text, forType: .string)
        } else if let url = meta["url"] as? String {
            item.setString(url, forType: .string)
            item.setString(url, forType: .URL)
        } else if let path = meta["image"] as? String, let data = try? Data(contentsOf: URL(fileURLWithPath: path)) {
            item.setData(data, forType: .png)
        } else {
            return false
        }
        return pb.writeObjects([item])
    }

    static func title(for text: String) -> String {
        let firstLine = text.split(whereSeparator: \.isNewline).first.map(String.init) ?? text
        let trimmed = firstLine.trimmingCharacters(in: .whitespaces)
        return trimmed.count > 80 ? String(trimmed.prefix(80)) + "…" : trimmed
    }

    private static func json(_ dict: [String: String]) -> String? {
        (try? JSONSerialization.data(withJSONObject: dict)).flatMap { String(data: $0, encoding: .utf8) }
    }

    private static func sha256(_ data: Data) -> String {
        SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
    }
}
